import React, { useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Save, Loader } from 'lucide-react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import toast from 'react-hot-toast';
import productService from '../../services/productService';
import ValidatedInput from '../../components/forms/ValidatedInput';
import { useWatch } from 'react-hook-form';

const productSchema = z.object({
    name: z.string().min(3, 'Product name must be at least 3 characters'),
    description: z.string().optional(),
    price: z.string().min(1, 'Price is required').transform(Number).pipe(
        z.number().min(0, 'Price cannot be negative')
    ),
    quantity: z.string().min(1, 'Quantity is required').transform(Number).pipe(
        z.number().int('Quantity must be a whole number').min(0, 'Quantity cannot be negative')
    ),
    sku: z.string().optional(),
    imageUrl: z.string().url('Must be a valid URL').optional().or(z.literal(''))
});

const ProductFormModal = ({ isOpen, onClose, product, onSuccess }) => {
    const queryClient = useQueryClient();
    const isEditing = !!product;

    const { register, handleSubmit, reset, formState: { errors } } = useForm({
        resolver: zodResolver(productSchema),
        defaultValues: {
            name: '',
            description: '',
            price: '',
            quantity: '',
            sku: '',
            imageUrl: ''
        }
    });

    useEffect(() => {
        if (product) {
            reset({
                name: product.name,
                description: product.description || '',
                price: product.price.toString(),
                quantity: product.quantity.toString(),
                sku: product.sku || '',
                imageUrl: product.imageUrl || ''
            });
        } else {
            reset({
                name: '',
                description: '',
                price: '',
                quantity: '',
                sku: '',
                imageUrl: ''
            });
        }
    }, [product, reset]);

    const mutation = useMutation({
        mutationFn: (data) => {
            const productData = {
                ...data,
                price: parseFloat(data.price),
                quantity: parseInt(data.quantity)
            };

            return isEditing
                ? productService.updateProduct(product.id, productData)
                : productService.createProduct(productData);
        },
        onSuccess: () => {
            toast.success(isEditing ? 'Product updated successfully' : 'Product created successfully');
            queryClient.invalidateQueries(['products']);
            onSuccess();
        },
        onError: (error) => {
            toast.error(error.response?.data?.message || 'Operation failed');
        }
    });

    const onSubmit = (data) => {
        mutation.mutate(data);
    };

    return (
        <AnimatePresence>
            {isOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="fixed inset-0 bg-black/50 backdrop-blur-sm"
                        onClick={onClose}
                    />

                    <motion.div
                        initial={{ opacity: 0, scale: 0.95, y: 20 }}
                        animate={{ opacity: 1, scale: 1, y: 0 }}
                        exit={{ opacity: 0, scale: 0.95, y: 20 }}
                        className="relative bg-white dark:bg-gray-800 rounded-2xl shadow-xl w-full max-w-2xl max-h-[90vh] overflow-y-auto"
                    >
                        {/* Header */}
                        <div className="flex items-center justify-between p-6 border-b border-gray-200 dark:border-gray-700">
                            <h2 className="text-xl font-bold text-gray-900 dark:text-white">
                                {isEditing ? 'Edit Product' : 'Add New Product'}
                            </h2>
                            <button
                                onClick={onClose}
                                className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors"
                            >
                                <X className="h-5 w-5 text-gray-500" />
                            </button>
                        </div>

                        {/* Form */}
                        <form onSubmit={handleSubmit(onSubmit)} className="p-6 space-y-4">
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <ValidatedInput
                                    label="Product Name"
                                    name="name"
                                    required
                                    error={errors.name?.message}
                                    {...register('name')}
                                />

                                <ValidatedInput
                                    label="SKU"
                                    name="sku"
                                    placeholder="Auto-generated if empty"
                                    error={errors.sku?.message}
                                    {...register('sku')}
                                />
                            </div>

                            <ValidatedInput
                                label="Description"
                                name="description"
                                placeholder="Product description..."
                                error={errors.description?.message}
                                {...register('description')}
                            />

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <ValidatedInput
                                    label="Price"
                                    name="price"
                                    type="number"
                                    step="0.01"
                                    required
                                    error={errors.price?.message}
                                    {...register('price')}
                                />

                                <ValidatedInput
                                    label="Quantity"
                                    name="quantity"
                                    type="number"
                                    required
                                    error={errors.quantity?.message}
                                    {...register('quantity')}
                                />
                            </div>

                            <ValidatedInput
                                label="Image URL"
                                name="imageUrl"
                                placeholder="https://example.com/image.jpg"
                                error={errors.imageUrl?.message}
                                {...register('imageUrl')}
                            />

                            {/* Preview */}
                            {watch('imageUrl') && (
                                <div className="mt-2">
                                    <p className="text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">Preview</p>
                                    <img
                                        src={watch('imageUrl')}
                                        alt="Preview"
                                        className="h-32 w-32 object-cover rounded-lg border border-gray-200 dark:border-gray-700"
                                        onError={(e) => { e.target.style.display = 'none'; }}
                                    />
                                </div>
                            )}

                            {/* Actions */}
                            <div className="flex items-center justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
                                <button
                                    type="button"
                                    onClick={onClose}
                                    className="px-4 py-2 text-sm font-medium text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors"
                                >
                                    Cancel
                                </button>

                                <button
                                    type="submit"
                                    disabled={mutation.isLoading}
                                    className="flex items-center gap-2 px-6 py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                                >
                                    {mutation.isLoading ? (
                                        <>
                                            <Loader className="h-4 w-4 animate-spin" />
                                            Saving...
                                        </>
                                    ) : (
                                        <>
                                            <Save className="h-4 w-4" />
                                            {isEditing ? 'Update Product' : 'Create Product'}
                                        </>
                                    )}
                                </button>
                            </div>
                        </form>
                    </motion.div>
                </div>
            )}
        </AnimatePresence>
    );
};



export default ProductFormModal;
